/* Teacher mascot: scanline-dither renderer + idle animation.
 *
 *   window.MOE_MASCOT   → pixel layers generated by moe/mascot.py
 *   window.TeacherDither → this renderer
 *
 * THE ONE RULE
 * ------------
 * This file contains no artwork and no rules. Every pixel of the character
 * arrives from Python. The renderer only decides which of those pixels get an
 * ink dash, and when. If the drawing changed, the generator changes -- same
 * rule the compliance checker follows, for the same reason: a second copy of
 * anything load-bearing will eventually disagree with the first.
 *
 * HOW THE DITHER WORKS
 * -------------------
 * 1. Composite the layers (base + swaying arm + eyes) into a 32x32
 *    luminance buffer.
 * 2. Compare each pixel against an 8x8 Bayer threshold matrix. Below
 *    threshold → ink.
 * 3. Draw the ink decisions as 1px-tall dashes on a fixed 3px vertical
 *    pitch.
 *
 * Step 3 is what turns ordinary 1-bit dithering into scanline art. Shading
 * stops being "darker pixels" and becomes "more dashes surviving per band",
 * which is what gives the character its printed, mechanical texture instead
 * of a smooth gradient.
 */
(function (global) {
  'use strict';

  var D = global.MOE_MASCOT;
  if (!D) return;

  var W = D.w, H = D.h, LUM = D.lum;
  var PITCH = 3;      // vertical px between dashes
  var SCALE = 5;      // output px per source px
  var DPR_CAP = 2;    // never render above this, or phones melt

  // ---- Bayer 8x8 threshold matrix -----------------------------------------
  // Built by recursion, which is exact. A hand-typed matrix is a typo waiting
  // to happen, and a wrong threshold matrix does not error -- it just makes
  // the art look subtly worse, forever.
  function bayer(n) {
    var m = [[0]];
    while (m.length < n) {
      var s = m.length, o = [], x, y;
      for (y = 0; y < s * 2; y++) o.push(new Array(s * 2));
      for (y = 0; y < s; y++) {
        for (x = 0; x < s; x++) {
          var v = 4 * m[y][x];
          o[y][x] = v; o[y][x + s] = v + 2;
          o[y + s][x] = v + 3; o[y + s][x + s] = v + 1;
        }
      }
      m = o;
    }
    return m.map(function (r) {
      return r.map(function (v) { return (v + 0.5) / (n * n); });
    });
  }
  var T = bayer(8);

  // ---- layer compositing ---------------------------------------------------
  // Three grids merged into one luminance buffer per frame. Kept as flat
  // arrays of luminance values so the inner loop never touches strings.
  var baseLum = gridLum(D.base);
  var armLum = gridLum(D.arm);
  var SKIN = LUM['L'];

  function gridLum(rows) {
    var out = new Float32Array(W * H);
    for (var y = 0; y < H; y++) {
      for (var x = 0; x < W; x++) {
        var ch = rows[y][x];
        if (ch !== '.') out[y * W + x] = LUM[ch];
      }
    }
    return out;
  }

  var buf = new Float32Array(W * H);

  function compose(armDx, armDy, blink, pupilDx, pupilDy) {
    buf.set(baseLum);
    // Arm on top of the torso, offset. Clamped so a sway can never push the
    // pointer off the canvas and silently amputate it.
    //
    // The emptiness test must be on the CHARACTER, never on the luminance.
    // The arm outline is "K", whose luminance is exactly 0 -- so testing
    // `v === 0` silently discarded every outline pixel and the arm never
    // appeared at all, while still counting as "drawn". Luminance 0 means
    // solid ink, which is the opposite of absent.
    for (var y = 0; y < H; y++) {
      for (var x = 0; x < W; x++) {
        if (D.arm[y][x] === '.') continue;
        var v = armLum[y * W + x];
        var nx = x + armDx, ny = y + armDy;
        if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue;
        buf[ny * W + nx] = v;
      }
    }
    // Eyes, with pupils nudged toward the pointer. Clamped to ±1px: any more
    // and the pupil slides out of the glasses frame and reads as a bug.
    var pdx = Math.max(-1, Math.min(1, pupilDx | 0));
    var pdy = Math.max(-1, Math.min(1, pupilDy | 0));
    for (y = 0; y < H; y++) {
      for (x = 0; x < W; x++) {
        if (D.eyes[y][x] !== '.') buf[y * W + x] = SKIN;   // blink = skin
      }
    }
    if (!blink) {
      [[D.eye_l[0], D.eye_l[1]], [D.eye_r[0], D.eye_r[1]]].forEach(function (e) {
        var ex = e[0] + pdx, ey = e[1] + pdy;
        for (var dy = -1; dy <= 1; dy++) {
          for (var dx = -1; dx <= 1; dx++) {
            var nx = ex + dx, ny = ey + dy;
            if (nx >= 0 && nx < W && ny >= 0 && ny < H) buf[ny * W + nx] = 0;
          }
        }
      });
    }
  }

  // ---- render --------------------------------------------------------------
  var PITCH_PX = PITCH * SCALE;

  function draw(ctx, glitchSeed) {
    ctx.clearRect(0, 0, W * SCALE, H * SCALE);
    ctx.fillStyle = '#0d0d0d';
    var w = ctx.canvas.width / (W * SCALE);
    for (var y = 0; y < H; y++) {
      // The glitch displaces whole bands horizontally, not the whole sprite.
      // Displacing everything reads as a loading error; displacing 3 of 32
      // rows reads as a signal fault, which is the intent.
      var glitch = glitchSeed > 0 && ((y + glitchSeed) % 11 === 0);
      var dx = glitch ? (glitchSeed % 3 - 1) * SCALE : 0;
      for (var x = 0; x < W; x++) {
        if (buf[y * W + x] >= T[y & 7][x & 7]) continue;
        ctx.fillRect((x * SCALE + dx) * w, Math.floor(y / PITCH) * PITCH_PX * w,
                     SCALE * w, Math.max(1, (1 / PITCH) * PITCH_PX * w));
      }
    }
  }

  // ---- animation -----------------------------------------------------------
  // Always animate — no reduced-motion check. Mobile users get the same
  // experience as desktop.
  var reduced = false;

  function mount(canvas) {
    if (!canvas || !canvas.getContext) return null;
    var ctx = canvas.getContext('2d');
    if (!ctx) return null;

    var dpr = Math.min(DPR_CAP, global.devicePixelRatio || 1);
    canvas.width = W * SCALE * dpr;
    canvas.height = H * SCALE * dpr;

    var t0 = Date.now(), blinkAt = 0, blinkUntil = 0, glitchUntil = 0;
    var mx = 0, my = 0, awake = 0, timer = null;

    // A static, fully-open frame. Drawn before any animation so the mascot is
    // never an empty box, and reused verbatim for reduced-motion.
    function still() { compose(0, 0, false, 0, 0); draw(ctx, 0); }
    still();

    function frame() {
      var t = (Date.now() - t0) / 1000;

      // Blink every ~3.4s for ~120ms. Idle blinking is what separates a
      // character from a logo.
      if (t > blinkAt) { blinkAt = t + 3.4 + (t % 1.7); blinkUntil = t + 0.12; }
      var blinking = t < blinkUntil;

      // Arm sway. Amplitude matters: at ±1 source pixel the arm barely
      // moves, and rounding a small sine quantises it to a value that looks
      // frozen. ±2 at this scale is a visible shift without detaching the
      // hand from the shoulder.
      var swayAmp = awake > 0 ? 2.4 : 1.6;
      var sway = Math.sin(t * (awake > 0 ? 1.7 : 0.9)) * swayAmp;

      // Glitch: rare, brief, never during the first second.
      if (t > 1 && t > glitchUntil + 4 + (t % 3)) glitchUntil = t + 0.18;

      // Pupils drift slowly back to centre when the pointer leaves.
      mx *= 0.9; my *= 0.9;

      compose(Math.round(sway), awake > 0 ? Math.round(sway * 0.5) : 0,
              blinking, mx, my);
      draw(ctx, t < glitchUntil ? Math.round(t * 60) + 1 : 0);
    }

    if (!reduced) {
      // 15fps, not 60. The source is 32px; a higher rate only burns battery
      // and makes the scanlines shimmer.
      timer = setInterval(frame, 1000 / 15);

      global.addEventListener('mousemove', function (ev) {
        if (ev.clientX == null) return;
        var cx = (canvas.offsetLeft || 0) + canvas.offsetWidth / 2;
        var dx = ((ev.clientX - cx) / 90);
        mx = Math.max(-1, Math.min(1, dx));
        my = Math.max(-1, Math.min(1, ((ev.clientY - canvas.offsetTop) / 90) - 0.15));
        awake = 1;
      });
      canvas.addEventListener('mouseenter', function () { awake = 1; });
      canvas.addEventListener('mouseleave', function () { awake = 0; });
    }

    return {
      render: frame,
      stop: function () { if (timer) clearInterval(timer); timer = null; },
      reduced: reduced
    };
  }

  global.TeacherDither = { mount: mount, bayer: bayer, THRESHOLD: T,
                          PITCH: PITCH, SCALE: SCALE };
})(typeof window !== 'undefined' ? window : this);
